(function(){
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const n=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}),number=v=>Number.isFinite(v)?n.format(v):'—',pct=v=>Number.isFinite(v)?n.format(v)+'%':'—';
 const date=v=>v?new Date(v+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short',timeZone:'UTC'}):'—';
 const stamp=v=>v?new Date(v).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' МСК':'нет снимка';
 window.createPultConversion=function(options={}){
  window.__pultConversion?.destroy?.();
  let panel=document.getElementById('conversion-panel');
  if(!panel){panel=document.createElement('section');panel.id='conversion-panel';const anchor=document.getElementById('sales-decline')||document.getElementById('ins-products-panel')||document.getElementById('products');if(anchor)anchor.after(panel);else return null;}
  panel.classList.add('panel','conversion-panel');
  panel.innerHTML=`<div class="panel-heading"><div><span class="eyebrow">ВОРОНКА ПО ТОВАРАМ</span><h2>Конверсия: что изменилось в заказах</h2><p>Сравниваем полные периоды и отделяем сигналы от предположений</p></div><button type="button" class="button secondary" id="conversion-refresh">↻ Проверить обновления</button></div><div class="conversion-body"><div id="conversion-state" class="conversion-state" role="status" aria-live="polite">Загружаем воронку…</div><div id="conversion-coverage" class="conversion-coverage"></div><div class="product-controls"><label class="search-label">Найти товар<input id="conversion-search" type="search" placeholder="Название, артикул, SKU"></label><label>Показать<select id="conversion-filter"><option value="declining">Снизились заказы</option><option value="all">Все товары с воронкой</option></select></label></div><p class="conversion-legend">В ячейках: предыдущий период → текущий. «—» означает, что показатель нельзя рассчитать. Даты воронки указаны отдельно от финансовой сводки.</p><div class="table-wrap"><table class="conversion-table"><thead><tr><th>Товар / магазин</th><th class="numeric">Заказано, шт.</th><th class="numeric">Переходы / просмотры</th><th class="numeric">В корзину</th><th class="numeric">Корзина: событий на 100</th><th class="numeric">Заказы / корзины</th><th>Сигналы и проверка</th></tr></thead><tbody id="conversion-rows"></tbody></table></div><div class="pagination"><span id="conversion-count"></span><div><button type="button" class="button secondary" id="conversion-prev" aria-label="Предыдущая страница воронки">←</button><button type="button" class="button secondary" id="conversion-next" aria-label="Следующая страница воронки">→</button></div></div><details class="conversion-method"><summary>Как считать конверсию и понимать сигналы</summary><div id="conversion-notes"></div><p>Показываем только однозначно сопоставленные товары. Отсутствие товара в РНП не означает отсутствие заказов. Малую выборку отмечаем отдельно; это не оценка статистической значимости.</p></details><p id="conversion-freshness" class="conversion-legend"></p></div>`;
  const $=id=>panel.querySelector('#'+id),market=document.getElementById('market'),store=document.getElementById('store'),globalRefresh=document.getElementById('refresh-view'),reset=document.getElementById('reset');
  const api=options.api||async function(url){const r=await fetch(url,{credentials:'same-origin'});const value=await r.json();if(!r.ok)throw Error('Не удалось загрузить воронку.');return value;};
  let result=null,page=1,generation=0,timer=null,destroyed=false;const pageSize=12;
  const pair=(row,key,percent=false)=>'<span>'+esc((percent?pct:number)(row.previous?.[key]))+'</span><b>'+esc((percent?pct:number)(row.current?.[key]))+'</b>';
  function rowMarkup(r){
   const ozon=r.market==='Ozon',eventLabel=ozon?'Просмотры карточки':'Переходы в карточку',cartLabel=ozon?'на 100 просмотров карточки':'на 100 переходов в карточку';
   const signals=(r.signals||[]).map(s=>{const format=s.unit==='percent'?pct:number;return '<article><strong>'+esc(s.title)+'</strong><p>'+esc(format(s.previous))+' → '+esc(format(s.current))+(s.unit==='percent'?' · '+number(s.current-s.previous)+' п. п.':s.unit==='per100'?' на 100 просмотров':'')+'</p><p>'+esc(s.action)+'</p></article>';}).join('');
   return '<tr><td><strong>'+esc(r.name)+'</strong><span class="sub">'+esc(r.market)+' · '+esc(r.storeName)+' · '+esc(r.offer_id)+' · '+esc(r.sku)+'</span>'+(r.lowSample?'<span class="conversion-sample">Мало данных для уверенного вывода</span>':'')+'</td><td class="numeric conversion-pair">'+pair(r,'orders')+(r.declining?'<small class="conversion-drop">−'+number(r.drop)+' шт. · −'+number(r.dropPercent)+'%</small>':'')+'</td><td class="numeric conversion-pair">'+pair(r,'visits')+'<small class="sub">'+eventLabel+'</small></td><td class="numeric conversion-pair">'+pair(r,'carts')+'</td><td class="numeric conversion-pair">'+pair(r,'cartConversionPct')+'<small class="sub">'+cartLabel+'</small></td><td class="numeric conversion-pair">'+(ozon?'<span>Не рассчитывается</span>':pair(r,'cartToOrderPct',true))+'</td><td><details><summary>'+esc(r.signals?.length?r.signals.map(s=>s.title).join(' · '):r.declining?'Падение заказов есть; причина не установлена':'Проверка изменений')+'</summary><div class="conversion-signals">'+signals+'<p>'+esc(r.hypothesisNote)+'</p></div></details></td></tr>';
  }
  function paint(){
   const q=$('conversion-search').value.trim().toLocaleLowerCase('ru'),onlyDeclines=$('conversion-filter').value==='declining';
   const rows=(result?.rows||[]).filter(r=>(!onlyDeclines||r.declining)&&(!q||[r.name,r.offer_id,r.sku,r.storeName].join(' ').toLocaleLowerCase('ru').includes(q))),pages=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.min(Math.max(page,1),pages);
   $('conversion-rows').innerHTML=rows.slice((page-1)*pageSize,page*pageSize).map(rowMarkup).join('')||'<tr><td colspan="7" class="empty">'+(result?.rows?.length?'Нет товаров по выбранному условию. Выберите «Все товары с воронкой», чтобы увидеть конверсию.':'Нет сопоставимой воронки. Причина указана выше; пропуски не заменяются нулями.')+'</td></tr>';
   $('conversion-count').textContent=rows.length+' товаров · '+page+' / '+pages;$('conversion-prev').disabled=page===1;$('conversion-next').disabled=page===pages;
  }
  function render(){
   const stale=result.status==='stale';$('conversion-state').classList.toggle('is-warning',stale||result.status==='unavailable');
   $('conversion-state').textContent=stale?'Обновление не удалось. Ниже сохранённое сравнение с прежним временем загрузки.':result.rows.length?'Показана воронка доступных товаров. Сигналы не доказывают причину падения заказов.':'Воронка выбранных магазинов пока недоступна.';
   $('conversion-coverage').innerHTML=(result.stores||[]).map(s=>'<article><strong>'+esc(s.name)+'</strong>'+(s.current&&s.previous?'<p>'+s.days+' дней: '+date(s.previous.from)+' — '+date(s.previous.to)+' → '+date(s.current.from)+' — '+date(s.current.to)+'</p>':'')+(s.coverage?.catalog!==null&&s.coverage?.catalog!==undefined?'<p>Воронка сопоставлена: <b>'+number(s.coverage.mapped)+' из '+number(s.coverage.catalog)+'</b> товаров каталога. '+(s.market==='Ozon'?'SKU с аналитикой: ':'Отслеживается в РНП: ')+number(s.coverage.tracked)+'.'+(s.coverage.unmapped?' Не сопоставлено: '+number(s.coverage.unmapped)+'.':'')+'</p>':'')+'<p>'+esc(s.reason||'')+'</p>'+(s.sourceLag?'<p>Последние доступные данные старше вчерашнего дня; даты показаны выше.</p>':'')+(s.rows?.length?'<small>'+esc(s.status==='stale'?'Сохранённый снимок: ':'Загружено: ')+esc(stamp(s.fetchedAt))+'</small>':'')+'</article>').join('');
   $('conversion-notes').innerHTML=(result.notes||[]).map(note=>'<p>'+esc(note)+'</p>').join('');
   $('conversion-freshness').textContent='Источник: '+result.source+' · проверка данных каждые 30 минут. Кнопка обновляет представление; до истечения срока используется сохранённый результат.';
   paint();
  }
  async function load(){
   const version=++generation;clearTimeout(timer);result=null;page=1;$('conversion-refresh').disabled=true;panel.setAttribute('aria-busy','true');$('conversion-state').textContent='Загружаем воронку выбранных магазинов…';$('conversion-coverage').innerHTML='';$('conversion-notes').innerHTML='';$('conversion-freshness').textContent='';$('conversion-rows').innerHTML='<tr><td colspan="7" class="empty">Проверяем полные периоды и привязку товаров…</td></tr>';$('conversion-count').textContent='';
   const params=new URLSearchParams({market:market?.value||'all'});if(store?.value)params.set('store',store.value);
   try{const data=await api('/api/conversion?'+params);if(destroyed||generation!==version)return;if(!Array.isArray(data?.stores)||!Array.isArray(data.rows))throw Error('schema');result=data;render();}
   catch{if(destroyed||generation!==version)return;$('conversion-state').textContent='Не удалось прочитать воронку. Нажмите «Проверить обновления», чтобы повторить.';$('conversion-state').classList.add('is-warning');$('conversion-rows').innerHTML='<tr><td colspan="7" class="empty">Данные не загружены. Нулевые показатели не подставлены.</td></tr>';}
   finally{if(!destroyed&&generation===version){$('conversion-refresh').disabled=false;panel.setAttribute('aria-busy','false');timer=setTimeout(load,30*60*1000);}}
  }
  const refresh=()=>void load(),resetFilters=()=>setTimeout(refresh,0);
  $('conversion-search').oninput=$('conversion-filter').onchange=()=>{page=1;paint()};$('conversion-prev').onclick=()=>{page--;paint()};$('conversion-next').onclick=()=>{page++;paint()};$('conversion-refresh').onclick=refresh;
  market?.addEventListener('change',refresh);store?.addEventListener('change',refresh);globalRefresh?.addEventListener('click',refresh);reset?.addEventListener('click',resetFilters);
  const service={refresh,destroy(){destroyed=true;++generation;clearTimeout(timer);market?.removeEventListener('change',refresh);store?.removeEventListener('change',refresh);globalRefresh?.removeEventListener('click',refresh);reset?.removeEventListener('click',resetFilters);}};window.__pultConversion=service;void load();return service;
 };
})();
